from django.db import models

class Penerbit(models.Model):
    nama = models.CharField(max_length=100, unique=True)
    def __str__(self):
        return self.nama

class Penulis(models.Model):
    nama = models.CharField(max_length=100)
    def __str__(self):
        return self.nama

class Buku(models.Model):
    judul = models.CharField(max_length=200)
    isbn = models.CharField(max_length=13, unique=True)
    tahun = models.PositiveSmallIntegerField()
    penerbit = models.ForeignKey(Penerbit, on_delete=models.PROTECT, related_name="buku")
    penulis = models.ManyToManyField(Penulis, related_name="buku")

    def __str__(self):
        return f"{self.judul} ({self.tahun})"

# N+1: satu query untuk buku, lalu satu query lagi untuk penulis setiap buku
for b in Buku.objects.all():
    print(b.judul, [p.nama for p in b.penulis.all()])

# 2 query saja: buku, lalu semua penulisnya sekaligus
for b in Buku.objects.select_related("penerbit").prefetch_related("penulis"):
    print(b.judul, b.penerbit.nama, [p.nama for p in b.penulis.all()])

