from django.shortcuts import get_object_or_404, redirect
from django.views.generic import DetailView
from .models import Produk

class DetailProduk(DetailView):
    model = Produk
    slug_field = 'slug'
    template_name = 'katalog/detail.html'
    context_object_name = 'produk'

def nonaktifkan(request, slug):
    if request.method != 'POST':
        return redirect('katalog:detail', slug=slug)
    p = get_object_or_404(Produk, slug=slug)
    p.aktif = False
    p.save(update_fields=['aktif'])
    return redirect('katalog:daftar')

