from django import forms
from django.core.validators import FileExtensionValidator

UKURAN_MAKS = 2 * 1024 * 1024   # 2 MB

class UnggahBuktiForm(forms.Form):
    bukti = forms.FileField(validators=[FileExtensionValidator(['jpg', 'jpeg', 'png', 'pdf'])])

    def clean_bukti(self):
        f = self.cleaned_data['bukti']
        if f.size > UKURAN_MAKS:
            raise forms.ValidationError('Ukuran berkas maksimal 2 MB.')
        return f

