from django.test import TestCase
from django.urls import reverse
from katalog.models import Kategori, Produk

class DaftarQueryTest(TestCase):
    def test_jumlah_query_tetap(self):
        k = Kategori.objects.create(nama='Minuman')
        for i in range(20):
            Produk.objects.create(nama=f'P{i}', slug=f'p{i}', harga=1000, kategori=k)
        with self.assertNumQueries(2):   # 1 hitung paginasi + 1 ambil produk+kategori
            self.client.get(reverse('katalog:daftar'))

from django.core.cache import cache
from django.db.models.signals import post_save
from django.dispatch import receiver
from .models import Produk

def produk_terlaris():
    data = cache.get('terlaris')
    if data is None:
        data = list(Produk.objects.order_by('-terjual')[:10].values('nama', 'terjual'))
        cache.set('terlaris', data, timeout=600)
    return data

@receiver(post_save, sender=Produk)
def bersihkan_cache(sender, instance, **kwargs):
    cache.delete('terlaris')

